+// validateDocumentReferences checks references before the importer makes any
+// changes to its creator. Otherwise, a failed import can leave behind flags,
+// variants, segments, or rules and produce a different result on retry.
+func validateDocumentReferences(doc *Document, namespace string) error {
+	if namespace == "" {
+		namespace = flipt.DefaultNamespace
+	}
+
+	segments := make(map[string]struct{}, len(doc.Segments))
+	for _, segment := range doc.Segments {
+		if segment != nil {
+			segments[segment.Key] = struct{}{}
+		}
+	}
+
+	for _, flag := range doc.Flags {
+		if flag == nil {
+			continue
+		}
+
+		variants := make(map[string]struct{}, len(flag.Variants))
+		for _, variant := range flag.Variants {
+			if variant != nil {
+				variants[variant.Key] = struct{}{}
+			}
+		}
+
+		checkSegment := func(index int, key string) error {
+			if _, ok := segments[key]; !ok {
+				return fmt.Errorf("flag %s/%s rule %d references unknown segment %q", namespace, flag.Key, index, key)
+			}
+			return nil
+		}
+
+		for index, rule := range flag.Rules {
+			if rule == nil {
+				continue
+			}
+
+			if rule.Segment != nil {
+				switch segment := rule.Segment.IsSegment.(type) {
+				case SegmentKey:
+					if err := checkSegment(index, string(segment)); err != nil {
+						return err
+					}
+				case *Segments:
+					if segment != nil {
+						for _, key := range segment.Keys {
+							if err := checkSegment(index, key); err != nil {
+								return err
+							}
+						}
+					}
+				}
+			}
+
+			for _, distribution := range rule.Distributions {
+				if distribution == nil {
+					continue
+				}
+				if _, ok := variants[distribution.VariantKey]; !ok {
+					return fmt.Errorf("flag %s/%s rule %d references unknown variant %q", namespace, flag.Key, index, distribution.VariantKey)
+				}
+			}
+		}
+
+		for index, rollout := range flag.Rollouts {
+			if rollout == nil || rollout.Segment == nil {
+				continue
+			}
+			if rollout.Segment.Key != "" {
+				if err := checkSegment(index, rollout.Segment.Key); err != nil {
+					return err
+				}
+			}
+			for _, key := range rollout.Segment.Keys {
+				if err := checkSegment(index, key); err != nil {
+					return err
+				}
+			}
+		}
+	}
+
+	return nil
+}
+
