	Version string   `yaml:"version,omitempty"`
	Include []string `yaml:"include,omitempty"`
	Exclude []string `yaml:"exclude,omitempty"`
}

// StoreSnapshot contains the structures necessary for serving
// flag state to a client.
type StoreSnapshot struct {
	ns        map[string]*namespace
	evalDists map[string][]*storage.EvaluationDistribution
	now       *timestamppb.Timestamp
}

type namespace struct {
	resource     *flipt.Namespace
	flags        map[string]*flipt.Flag
	segments     map[string]*flipt.Segment
	rules        map[string]*flipt.Rule
	rollouts     map[string]*flipt.Rollout
	evalRules    map[string][]*storage.EvaluationRule
	evalRollouts map[string][]*storage.EvaluationRollout
}

func newNamespace(key, name string, created *timestamppb.Timestamp) *namespace {
	return &namespace{
		resource: &flipt.Namespace{
			Key:       key,
			Name:      name,
			CreatedAt: created,
			UpdatedAt: created,
		},
		flags:        map[string]*flipt.Flag{},
		segments:     map[string]*flipt.Segment{},
		rules:        map[string]*flipt.Rule{},
		rollouts:     map[string]*flipt.Rollout{},
		evalRules:    map[string][]*storage.EvaluationRule{},
		evalRollouts: map[string][]*storage.EvaluationRollout{},
	}
}

// SnapshotFromFS is a convenience function for building a snapshot
// directly from an implementation of fs.FS using the list state files
// function to source the relevant Flipt configuration files.
func SnapshotFromFS(logger *zap.Logger, source fs.FS) (*StoreSnapshot, error) {
	files, err := listStateFiles(logger, source)
	if err != nil {
		return nil, err
	}

	logger.Debug("opening state files", zap.Strings("paths", files))

	return SnapshotFromPaths(source, files...)
}

// SnapshotFromPaths builds a snapshot from the provided paths after validating
// each configuration file.
func SnapshotFromPaths(source fs.FS, paths ...string) (*StoreSnapshot, error) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		return nil, err
	}

	var rds []io.Reader
	for _, path := range paths {
		contents, err := fs.ReadFile(source, path)
		if err != nil {
			return nil, fmt.Errorf("reading %s: %w", path, err)
		}

		if err := validator.Validate(path, contents); err != nil {
			return nil, err
		}

		rds = append(rds, bytes.NewReader(contents))
	}

	return snapshotFromReaders(rds...)
}

// snapshotFromReaders constructs a StoreSnapshot from the provided
// slice of io.Reader.
func snapshotFromReaders(sources ...io.Reader) (*StoreSnapshot, error) {
	now := timestamppb.Now()
	s := StoreSnapshot{
		ns: map[string]*namespace{
			defaultNs: newNamespace("default", "Default", now),
		},
		evalDists: map[string][]*storage.EvaluationDistribution{},
		now:       now,
	}

	for _, reader := range sources {
		doc := new(ext.Document)

		if err := yaml.NewDecoder(reader).Decode(doc); err != nil {
			return nil, err
		}

		// set namespace to default if empty in document
		if doc.Namespace == "" {
			doc.Namespace = "default"
		}

		if err := s.addDoc(doc); err != nil {
			return nil, err
		}

	}
	return &s, nil
}

func listStateFiles(logger *zap.Logger, source fs.FS) ([]string, error) {
	// This is the default variable + value for the FliptIndex. It will preserve its value if
	// a .flipt.yml can not be read for whatever reason.
	idx := FliptIndex{
		Version: "1.0",
		Include: []string{
			"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
		},
	}

	// Read index file
	inFile, err := source.Open(indexFile)
	if err == nil {
		if derr := yaml.NewDecoder(inFile).Decode(&idx); derr != nil {
			return nil, fmt.Errorf("yaml: %w", derr)
		}
	}

	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		} else {
			logger.Debug("index file does not exist, defaulting...", zap.String("file", indexFile), zap.Error(err))
		}
	}

	var includes []glob.Glob
	for _, g := range idx.Include {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling include glob: %w", err)
		}

		includes = append(includes, glob)
	}

	filenames := make([]string, 0)
	if err := fs.WalkDir(source, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return nil
		}

		for _, glob := range includes {
			if glob.Match(path) {
				filenames = append(filenames, path)
				return nil
			}
		}

		return nil
	}); err != nil {
		return nil, err
	}

	if len(idx.Exclude) > 0 {
		var excludes []glob.Glob
		for _, g := range idx.Exclude {
			glob, err := glob.Compile(g)
			if err != nil {
				return nil, fmt.Errorf("compiling include glob: %w", err)
			}

			excludes = append(excludes, glob)
		}

	OUTER:
		for i := range filenames {
			for _, glob := range excludes {
				if glob.Match(filenames[i]) {
					filenames = append(filenames[:i], filenames[i+1:]...)
					continue OUTER
				}
			}
		}
	}

	return filenames, nil

package ext

import (
	"context"
	"encoding/json"
	"fmt"
	"io"

	"github.com/blang/semver/v4"
	"go.flipt.io/flipt/errors"
	"go.flipt.io/flipt/rpc/flipt"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"gopkg.in/yaml.v2"
)

type Creator interface {
	GetNamespace(context.Context, *flipt.GetNamespaceRequest) (*flipt.Namespace, error)
	CreateNamespace(context.Context, *flipt.CreateNamespaceRequest) (*flipt.Namespace, error)
	CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
	CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
	CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
	CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
	CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
	CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
	CreateRollout(context.Context, *flipt.CreateRolloutRequest) (*flipt.Rollout, error)
}

type Importer struct {
	creator   Creator
	namespace string
	createNS  bool
}

type ImportOpt func(*Importer)

func WithNamespace(ns string) ImportOpt {
	return func(i *Importer) {
		i.namespace = ns
	}
}

func WithCreateNamespace() ImportOpt {
	return func(i *Importer) {
		i.createNS = true
	}
}

func NewImporter(store Creator, opts ...ImportOpt) *Importer {
	i := &Importer{
		creator: store,
	}

	for _, opt := range opts {
		opt(i)
	}

	return i
}

func (i *Importer) Import(ctx context.Context, r io.Reader) (err error) {
	var (
		dec = yaml.NewDecoder(r)
		doc = new(Document)
	)

	if err := dec.Decode(doc); err != nil {
		return fmt.Errorf("unmarshalling document: %w", err)
	}

	v := latestVersion
	if doc.Version != "" {
		v, err = semver.ParseTolerant(doc.Version)
		if err != nil {
			return fmt.Errorf("parsing document version: %w", err)
		}

		var found bool
		for _, sv := range supportedVersions {
			if found = sv.EQ(v); found {
				break
			}
		}

		if !found {
			return fmt.Errorf("unsupported version: %s", doc.Version)
		}
	}

	// check if document namespace matches cli namespace if both are set
	if doc.Namespace != "" && i.namespace != "" && doc.Namespace != i.namespace {
		return fmt.Errorf("namespace mismatch: namespaces must match in file and args if both provided: %s != %s", doc.Namespace, i.namespace)
	}

	// prefer document namespace over cli namespace, but use cli namespace if
	// document namespace is empty
	var namespace = doc.Namespace
	if namespace == "" {
		namespace = i.namespace
	}

	if err := validateDocumentReferences(doc, namespace); err != nil {
		return err
	}

	if i.createNS && namespace != "" && namespace != flipt.DefaultNamespace {
		_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
			Key: namespace,
		})

		if err != nil {
			if status.Code(err) != codes.NotFound && !errors.AsMatch[errors.ErrNotFound](err) {
				return err
			}

			_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
				Key:  namespace,
				Name: namespace,
			})
			if err != nil {
				return err
			}
		}
	}

	var (
		// map flagKey => *flag
		createdFlags = make(map[string]*flipt.Flag)
		// map segmentKey => *segment
		createdSegments = make(map[string]*flipt.Segment)
		// map flagKey:variantKey => *variant
		createdVariants = make(map[string]*flipt.Variant)
	)

	// create flags/variants
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		req := &flipt.CreateFlagRequest{
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			NamespaceKey: namespace,
		}

		// support explicitly setting flag type from 1.1
		if f.Type != "" {
			if err := ensureFieldSupported("flag.type", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
		}

		flag, err := i.creator.CreateFlag(ctx, req)
		if err != nil {
			return fmt.Errorf("creating flag: %w", err)
		}

		for _, v := range f.Variants {
			if v == nil {
				continue
			}

			var out []byte

			if v.Attachment != nil {
				converted := convert(v.Attachment)
				out, err = json.Marshal(converted)
				if err != nil {
					return fmt.Errorf("marshalling attachment: %w", err)
				}
			}

			variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
				FlagKey:      f.Key,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(out),
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating variant: %w", err)
			}

			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
		}

		createdFlags[flag.Key] = flag
	}

	// create segments/constraints
	for _, s := range doc.Segments {
		if s == nil {
			continue
		}

		segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
			Key:          s.Key,
			Name:         s.Name,
			Description:  s.Description,
			MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
			NamespaceKey: namespace,
		})

		if err != nil {
			return fmt.Errorf("creating segment: %w", err)
		}

		for _, c := range s.Constraints {
			if c == nil {
				continue
			}

			_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
				SegmentKey:   s.Key,
				Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
				Property:     c.Property,
				Operator:     c.Operator,
				Value:        c.Value,
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating constraint: %w", err)
			}
		}

		createdSegments[segment.Key] = segment
	}

	// create rules/distributions
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		// loop through rules
		for idx, r := range f.Rules {
			if r == nil {
				continue
			}

			// support implicit rank from version >=1.1
			rank := int32(r.Rank)
			if rank == 0 && v.GE(semver.Version{Major: 1, Minor: 1}) {
				rank = int32(idx) + 1
			}

			fcr := &flipt.CreateRuleRequest{
				FlagKey:      f.Key,
				Rank:         rank,
				NamespaceKey: namespace,
			}

			switch s := r.Segment.IsSegment.(type) {
			case SegmentKey:
				fcr.SegmentKey = string(s)
			case *Segments:
				fcr.SegmentKeys = s.Keys
				fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
			}

			rule, err := i.creator.CreateRule(ctx, fcr)

			if err != nil {
				return fmt.Errorf("creating rule: %w", err)
			}

			for _, d := range r.Distributions {
				if d == nil {
					continue
				}

				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
				if !found {
					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
				}

				_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
					FlagKey:      f.Key,
					RuleId:       rule.Id,
					VariantId:    variant.Id,
					Rollout:      d.Rollout,
					NamespaceKey: namespace,
				})

				if err != nil {
					return fmt.Errorf("creating distribution: %w", err)
				}
			}
		}

		// support explicitly setting flag type from 1.1
		if len(f.Rollouts) > 0 {
			if err := ensureFieldSupported("flag.rollouts", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			for idx, r := range f.Rollouts {
				if r.Segment != nil && r.Threshold != nil {
					return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
						namespace,
						f.Key,
						idx,
					)
				}

				req := &flipt.CreateRolloutRequest{
					NamespaceKey: namespace,
					FlagKey:      f.Key,
					Description:  r.Description,
					Rank:         int32(idx + 1),
				}

				if r.Segment != nil {
					frs := &flipt.RolloutSegment{
						Value:      r.Segment.Value,
						SegmentKey: r.Segment.Key,
					}

					if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
						return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
							namespace,
							f.Key,
							idx,
						)
					}

					// support explicitly setting only "keys" on rules from 1.2
					if len(r.Segment.Keys) > 0 {
						if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
							Major: 1,
							Minor: 2,
						}, v); err != nil {
							return err
						}

						frs.SegmentKeys = r.Segment.Keys
					}

					frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])

					req.Rule = &flipt.CreateRolloutRequest_Segment{
						Segment: frs,
					}
				} else if r.Threshold != nil {
					req.Rule = &flipt.CreateRolloutRequest_Threshold{
						Threshold: &flipt.RolloutThreshold{
							Percentage: r.Threshold.Percentage,
							Value:      r.Threshold.Value,
						},
					}
				}

				if _, err := i.creator.CreateRollout(ctx, req); err != nil {
					return fmt.Errorf("creating rollout: %w", err)
				}
			}
		}
	}

	return nil
}

// validateDocumentReferences checks references before the importer makes any
// changes to its creator. Otherwise, a failed import can leave behind flags,
// variants, segments, or rules and produce a different result on retry.
func validateDocumentReferences(doc *Document, namespace string) error {
	if namespace == "" {
		namespace = flipt.DefaultNamespace
	}

	segments := make(map[string]struct{}, len(doc.Segments))
	for _, segment := range doc.Segments {
		if segment != nil {
			segments[segment.Key] = struct{}{}
		}
	}

	for _, flag := range doc.Flags {
		if flag == nil {
			continue
		}

		variants := make(map[string]struct{}, len(flag.Variants))
		for _, variant := range flag.Variants {
			if variant != nil {
				variants[variant.Key] = struct{}{}
			}
		}

		checkSegment := func(index int, key string) error {
			if _, ok := segments[key]; !ok {
				return fmt.Errorf("flag %s/%s rule %d references unknown segment %q", namespace, flag.Key, index, key)
			}
			return nil
		}

		for index, rule := range flag.Rules {
			if rule == nil {
				continue
			}

			if rule.Segment != nil {
				switch segment := rule.Segment.IsSegment.(type) {
				case SegmentKey:
					if err := checkSegment(index, string(segment)); err != nil {
						return err
					}
				case *Segments:
					if segment != nil {
						for _, key := range segment.Keys {
							if err := checkSegment(index, key); err != nil {
								return err
							}
						}
					}
				}
			}

			for _, distribution := range rule.Distributions {
				if distribution == nil {
					continue
				}
				if _, ok := variants[distribution.VariantKey]; !ok {
					return fmt.Errorf("flag %s/%s rule %d references unknown variant %q", namespace, flag.Key, index, distribution.VariantKey)
				}
			}

package cue

import (
	_ "embed"
	"errors"
	"fmt"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerrors "cuelang.org/go/cue/errors"
	"cuelang.org/go/cue/token"
	"cuelang.org/go/encoding/yaml"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes one problem in a configuration file.
type Error struct {
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

// Result is a collection of errors that occurred during validation.
type Result struct {
	Errors []Error `json:"errors"`
}

type validationErrors []error

func (validationErrors) Error() string { return ErrValidationFailed.Error() }

func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }

func (e validationErrors) Unwrap() []error { return []error(e) }

// Unwrap returns the individual errors in a multi-error, including one wrapped
// by another error. The bool is false when err does not support this operation.
func Unwrap(err error) ([]error, bool) {
	var multi interface{ Unwrap() []error }
	if !errors.As(err, &multi) {
		return nil, false
	}

	return multi.Unwrap(), true
}

type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil {
		return nil, v.Err()
	}

	return &FeaturesValidator{
		cue: cctx,
		v:   v,
	}, nil
}

// Validate validates a YAML file against the CUE feature definition and checks
// references between rules, variants, and segments in the file.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract(file, b)
	if err != nil {
		return validationErrors(cueIssues(file, err))
	}

	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return validationErrors(cueIssues(file, err))
	}

	issues := cueIssues(file, v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true)))
	issues = append(issues, referenceIssues(file, yv)...)
	if len(issues) != 0 {
		return validationErrors(issues)
	}

	return nil
}

func cueIssues(file string, err error) []error {
	var issues []error
	for _, e := range cueerrors.Errors(err) {
		pos := token.NoPos
		if positions := cueerrors.Positions(e); len(positions) > 0 {
			pos = positions[len(positions)-1]
		}
		issues = append(issues, locatedError(file, e.Error(), pos))
	}
	return issues
}

func locatedError(file, message string, pos token.Pos) Error {
	location := Location{File: file, Line: pos.Line(), Column: pos.Column()}
	if location.Line == 0 {
		location.Line = 1
	}
	if location.Column == 0 {
		location.Column = 1
	}
	return Error{Message: message, Location: location}
}

func referenceIssues(file string, document cue.Value) []error {
	var issues []error

	namespace := "default"
	if value, err := document.LookupPath(cue.ParsePath("namespace")).String(); err == nil {
		namespace = value
	}

	segments := make(map[string]struct{})
	for _, segment := range listValues(document.LookupPath(cue.ParsePath("segments"))) {
		if key, err := segment.LookupPath(cue.ParsePath("key")).String(); err == nil {
			segments[key] = struct{}{}
		}
	}

	for _, flag := range listValues(document.LookupPath(cue.ParsePath("flags"))) {
		flagKey, err := flag.LookupPath(cue.ParsePath("key")).String()
		if err != nil {
			continue
		}

		variants := make(map[string]struct{})
		for _, variant := range listValues(flag.LookupPath(cue.ParsePath("variants"))) {
			if key, err := variant.LookupPath(cue.ParsePath("key")).String(); err == nil {
				variants[key] = struct{}{}
			}
		}

		for i, rule := range listValues(flag.LookupPath(cue.ParsePath("rules"))) {
			prefix := fmt.Sprintf("flag %s/%s rule %d", namespace, flagKey, i)
			issues = appendSegmentIssues(issues, file, prefix, segments, rule.LookupPath(cue.ParsePath("segment")))
			for _, distribution := range listValues(rule.LookupPath(cue.ParsePath("distributions"))) {
				variant := distribution.LookupPath(cue.ParsePath("variant"))
				key, err := variant.String()
				if err != nil {
					continue
				}
				if _, ok := variants[key]; !ok {
					issues = append(issues, locatedError(file, fmt.Sprintf("%s references unknown variant %q", prefix, key), variant.Pos()))
				}
			}
		}

		// Boolean flags use segment rollouts as well as rules. Report missing
		// segment keys with the same rule wording used for rule references.
		for i, rollout := range listValues(flag.LookupPath(cue.ParsePath("rollouts"))) {
			segment := rollout.LookupPath(cue.ParsePath("segment"))
			prefix := fmt.Sprintf("flag %s/%s rule %d", namespace, flagKey, i)
			issues = appendSegmentIssues(issues, file, prefix, segments, segment)
		}
	}

	return issues
}

func appendSegmentIssues(issues []error, file, prefix string, segments map[string]struct{}, value cue.Value) []error {
	if key, err := value.String(); err == nil {
		return appendUnknownSegment(issues, file, prefix, segments, value, key)
	}

	key := value.LookupPath(cue.ParsePath("key"))
	if name, err := key.String(); err == nil {
		issues = appendUnknownSegment(issues, file, prefix, segments, key, name)
	}
	for _, key := range listValues(value.LookupPath(cue.ParsePath("keys"))) {
		if name, err := key.String(); err == nil {
			issues = appendUnknownSegment(issues, file, prefix, segments, key, name)
		}
	}
	return issues
}

func appendUnknownSegment(issues []error, file, prefix string, segments map[string]struct{}, value cue.Value, key string) []error {
	if _, ok := segments[key]; !ok {
		issues = append(issues, locatedError(file, fmt.Sprintf("%s references unknown segment %q", prefix, key), value.Pos()))
	}
	return issues
}

func listValues(value cue.Value) []cue.Value {
	iter, err := value.List()
	if err != nil {
